import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

/**
 * Compose class names.
 *
 * Two jobs, and the second is the one that matters: `clsx` flattens
 * conditionals, then tailwind-merge resolves *conflicting* utilities by
 * keeping the last one. That is what makes the forwarding rule in
 * CONVENTIONS.md §5 true — a consumer passing `className="px-6"` to a component
 * whose default is `px-4` gets `px-6`, rather than two competing declarations
 * whose winner depends on stylesheet order.
 *
 * The configuration below is NOT optional. tailwind-merge only knows
 * Tailwind's default class names; the system's own utilities share the `text-`
 * prefix across two different properties (`text-button-sm` is a font size,
 * `text-ink-primary` is a colour), and without being told which is which the
 * merger guesses — and DELETES one. That is a silent failure with no build
 * error and no missing CSS: the class simply never reaches the DOM. It shipped
 * once: every md/sm button label rendered at the body's 16px because the size
 * utility was merged away by the variant's colour. Computed-style tests in the
 * browser suite now pin this.
 */
const twMerge = extendTailwindMerge({
  override: {
    conflictingClassGroups: {
      // Stock `text-sm` sets a font size AND a line height, so tailwind-merge
      // makes any font size clear a preceding `leading-*`. That deletion is
      // wrong here: `text-label-sm` once silently deleted `leading-flat` from
      // every Badge, and md and sm both rendered at 28px. Our roles DO carry
      // a line height now (ADR 0020 §3, as a Tailwind companion), but an
      // explicit `leading-*` beside one is a DECLARED exception to it, and
      // Tailwind lets it win through `--tw-leading` — so the merger must not
      // delete it either.
      //
      // Our roles have to live in the `font-size` group to be classified
      // correctly at all (a separate group makes `text-color` swallow them),
      // so the conflict is removed at the group level.
      //
      // The knowing trade: a consumer writing stock `leading-6 text-sm` keeps
      // both, and the cascade decides instead of the merger. That is a far
      // smaller failure than a component silently losing its own leading, and
      // it only affects stock classes this library never emits.
      "font-size": [],
    },
  },
  extend: {
    // The spacing scale's own step names. Registered on the shared scale so
    // every group that derives from it (p*, m*, gap*, space-*, inset-*)
    // merges: without this, a consumer's `px-6` failed to displace a
    // component's `px-md` — both survived and the winner fell to stylesheet
    // order, which is exactly what cn() exists to prevent.
    //
    // The PURPOSE-NAMED chrome dimensions ride the same scale, because the
    // emitter mints them into `--spacing-*` (nav, nav-rail, dialog-md,
    // dialog-lg — the widths check:utilities points bare steps at). They were
    // omitted here at first, so `cn("w-dialog-md", "w-full")` kept both and
    // a consumer could not displace Toast's width — the exact px-md failure,
    // one namespace over. The emitter and this list must move together; the
    // cn unit tests pin every name.
    theme: {
      spacing: [
        "xs", "sm", "md", "lg", "xl", "2xl", "3xl", "4xl",
        "nav", "nav-rail", "dialog-md", "dialog-lg",
      ],
    },
    classGroups: {
      // The type roles (--text-* namespace in the emitted theme). They must
      // sit in `font-size` — see the conflict override above.
      "font-size": [
        { text: [(value: string) => /^(display|title|body|label|button)-(lg|md|sm)$/.test(value) || value === "caption"] },
      ],
      // The ink roles. Namespaced `ink-*` precisely so this rule can be a
      // prefix match instead of a list that drifts.
      "text-color": [{ text: [(value: string) => value.startsWith("ink-")] }],
      // Custom names on default namespaces, so two weights or two leadings
      // still merge correctly.
      "font-weight": [{ font: ["regular", "book"] }],
      leading: [{ leading: ["flat"] }],
      // Stroke widths (ADR 0020 §2). tailwind-merge reads an unknown
      // `border-<word>` as a COLOUR, so without these `border-hairline` and
      // `border-edge-subtle` would share a group and one would be deleted.
      // A literal name is matched before any validator, which is what puts
      // these in the width group rather than the colour one.
      "border-w": [{ border: ["hairline", "thick"] }],
      "border-w-x": [{ "border-x": ["hairline", "thick"] }],
      "border-w-y": [{ "border-y": ["hairline", "thick"] }],
      "border-w-t": [{ "border-t": ["hairline", "thick"] }],
      "border-w-r": [{ "border-r": ["hairline", "thick"] }],
      "border-w-b": [{ "border-b": ["hairline", "thick"] }],
      "border-w-l": [{ "border-l": ["hairline", "thick"] }],
      "ring-w": [{ ring: ["hairline", "thick"] }],
      "outline-w": [{ outline: ["hairline", "thick", "focus"] }],
      "outline-offset": [{ "outline-offset": ["focus"] }],
    },
  },
});

export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}
